"use client";

import { useEffect, useState } from "react";

type Product = {
  id: number;
  product_name: string;
  category: string;
  price: number;
  stock_quantity: number;
};

export default function ProductsPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState("");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/products")
      .then((res) => res.json())
      .then((data) => setProducts(data));
  }, []);

  const filteredProducts = products.filter((product) =>
    `${product.product_name} ${product.category}`
      .toLowerCase()
      .includes(search.toLowerCase())
  );

  const totalStock = products.reduce(
    (sum, product) => sum + Number(product.stock_quantity || 0),
    0
  );

  const lowStock = products.filter(
    (product) => Number(product.stock_quantity) <= 10
  ).length;

  return (
    <main className="page-container products-page">
      <section className="page-header">
        <h1 className="page-title">Products</h1>
        <p className="page-subtitle">
          Green inventory and stock management design.
        </p>
      </section>

      <section className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📦</div>
          <p>Total Products</p>
          <h2>{products.length}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">⚠️</div>
          <p>Low Stock</p>
          <h2>{lowStock}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <p>Total Stock</p>
          <h2>{totalStock}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🔍</div>
          <p>Filtered</p>
          <h2>{filteredProducts.length}</h2>
        </div>
      </section>

      <input
        className="search-box"
        placeholder="Search products..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      <section className="table-card">
        <h2>Products List</h2>
        <p>{filteredProducts.length} records found</p>

        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Product Name</th>
                <th>Category</th>
                <th>Price</th>
                <th>Stock</th>
              </tr>
            </thead>

            <tbody>
              {filteredProducts.map((product) => (
                <tr key={product.id}>
                  <td>{product.id}</td>
                  <td>{product.product_name}</td>
                  <td>{product.category}</td>
                  <td>₹{Number(product.price).toFixed(2)}</td>
                  <td>{product.stock_quantity}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}